  '20:1': { surah: 20, ayah: 1, arabic: 'طه', translations: { ru: 'Та. Ха.', inh: 'ТIоа. ХIа́.' }, editions: { arabic: 'ar-quran-uthmani', ru: 'ru-kuliev' }, fetchedAt: '2026-05-08' },
