  '51:1': { surah: 51, ayah: 1, arabic: 'وَٱلذَّٰرِيَٰتِ ذَرْوًۭا', translations: { ru: 'Клянусь рассеивающими прах!', inh: 'Дом бахьаш хье́кхача михаех дув буъ Аз.' }, editions: { arabic: 'ar-quran-uthmani', ru: 'ru-kuliev' }, fetchedAt: '2026-05-08' },
  '51:2': { surah: 51, ayah: 2, arabic: 'فَٱلْحَٰمِلَٰتِ وِقْرًۭا', translations: { ru: 'Клянусь несущими бремя!', inh: 'Езача морхех дув буъ Аз.' }, editions: { arabic: 'ar-quran-uthmani', ru: 'ru-kuliev' }, fetchedAt: '2026-05-08' },
